+{
+	if (!opt)
+		return -EINVAL;
+
+	if (!strncmp(opt, "on", 2)) {
+		static_branch_enable(&use_tc_as_sched_clock);
+		pr_info("Using TC instead of jiffies as source of sched_clock()\n");
+	}
